#!/usr/bin/env bash
set -euo pipefail

UPSTREAM_URL="https://raw.githubusercontent.com/wikimedia/mediawiki-docker/main/1.43/fpm/Dockerfile"
PHP_TAG="8.3.36-fpm"
OUTPUT="Dockerfile.patch"

cd "$(dirname "$0")/.."

echo "Fetching MediaWiki Dockerfile from upstream..."
UPSTREAM_CONTENT=$(curl -sSL "$UPSTREAM_URL")

echo "Generating $OUTPUT..."
cat << 'HEADER' > "$OUTPUT"
# syntax=docker/dockerfile:1
# AUTO-GENERATED FILE. DO NOT EDIT DIRECTLY.
#
# Generated by hack/gen-dockerfile-patch.sh:
# 1. MediaWiki Dockerfile fetched from:
#    https://github.com/wikimedia/mediawiki-docker/blob/main/1.43/fpm/Dockerfile
#    with base image version replaced:
#    FROM php:8.3-fpm -> FROM php:8.3.36-fpm AS mediawiki
# 2. Appended with the contents of Dockerfile verbatim.

HEADER

# Replace FROM php:8.3-fpm with FROM php:8.3.36-fpm AS mediawiki
echo "$UPSTREAM_CONTENT" | sed "s|^FROM php:8\.3-fpm|FROM php:${PHP_TAG} AS mediawiki|" >> "$OUTPUT"

echo "" >> "$OUTPUT"
echo "# -----------------------------------------------------------------------------" >> "$OUTPUT"
echo "# Original Dockerfile contents appended below" >> "$OUTPUT"
echo "# -----------------------------------------------------------------------------" >> "$OUTPUT"
echo "" >> "$OUTPUT"

# Append Dockerfile without leading '# syntax=' and replace base stage source
grep -v '^# syntax=' Dockerfile | sed 's|^FROM mediawiki:.* AS base|FROM mediawiki AS base|' >> "$OUTPUT"

echo "Done generating $OUTPUT."
